        "lab.perfectSentence0": ("Maya ___ three chapters so far.", "Maya ___ three chapters so far."),
        "lab.perfectSentence1": ("I ___ for an hour, and I still haven't reached the station.", "I ___ for an hour, and I still haven't reached the station."),
        "lab.perfectSentence2": ("We ___ each other since 2018.", "We ___ each other since 2018."),
        "lab.perfectOption00": ("has been reading", "has been reading"), "lab.perfectOption01": ("has read", "has read"),
