        "lab.linearSystemCheck": ("Проверить прогноз", "Check prediction"),
        "lab.linearSystemCorrect": ("Верно. Сверь вывод с результатом исключения: он показывает число решений системы.", "Correct. Compare it with the elimination result, which determines how many solutions the system has."),
        "lab.linearSystemReview": ("Сравни результат после сложения: противоречие означает 0 = ненулевое число; тождество означает 0 = 0.", "Compare the elimination result: a contradiction is 0 = a nonzero number; an identity is 0 = 0."),
        "lab.linearSystemRetry": ("Попробовать ещё раз с перемешанными вариантами", "Retry with shuffled choices"),
        "lab.linearSystemNew": ("Новый прогноз", "New prediction"),
        "lab.linearSystemOutcomeOne": ("Одна точка пересечения: (%.0f, %.0f).", "One intersection: (%.0f, %.0f)."),
        "lab.linearSystemOutcomeNone": ("Получилось противоречие, поэтому общих точек нет.", "The result is a contradiction, so there is no common point."),
        "lab.linearSystemOutcomeInfinite": ("Получилось тождество: это одна прямая с бесконечным числом решений.", "The result is an identity: one line with infinitely many solutions."),
        "lab.complexityHint": ("Сравни худший случай по числу сравнений. Это не замер секунд и не честное сравнение бинарного и линейного поиска по реальной скорости.", "Compare the worst case by number of comparisons. This is not a timing test or a claim about real-world speed."),
        "lab.complexitySize": ("Размер отсортированного списка: %d элементов", "Sorted list size: %d items"),
        "lab.complexityLinear": ("Линейный поиск O(n)", "Linear search O(n)"),
        "lab.complexityBinary": ("Бинарный O(log n)", "Binary search O(log n)"),
        "lab.complexityComparisons": ("до %d сравнений", "up to %d comparisons"),
        "lab.complexityPrecondition": ("Бинарный поиск требует заранее отсортированный список.", "Binary search requires an already sorted list."),
        "lab.complexityLimit": ("Сортировка и вставка тоже требуют работы: bisect ищет позицию за O(log n), но insort со сдвигом элементов остаётся O(n). Полосы отражают только число сравнений.", "Sorting and insertion also take work: bisect finds a position in O(log n), but insort remains O(n) because list items must shift. Bars represent comparison counts only."),
        "lab.dataStructures.title": ("Выбери структуру под операции", "Choose a structure for the operations"),
        "lab.dataStructures.hint": ("Сначала реши, важны ли порядок, повторы, проверка принадлежности или связь ключа со значением. Здесь не измеряются секунды.", "First decide whether order, duplicates, membership, or a key-to-value mapping matters. This does not measure runtime."),
        "lab.dataStructures.progress": ("Сценарий %d из %d", "Scenario %d of %d"),
        "lab.dataStructures.choicePicker": ("Структура данных", "Data structure"),
        "lab.dataStructures.choose": ("Выбери структуру", "Choose a structure"),
        "lab.dataStructures.choice.list": ("list — упорядоченная последовательность", "list — ordered sequence"),
        "lab.dataStructures.choice.set": ("set — множество уникальных значений", "set — unique values"),
        "lab.dataStructures.choice.dict": ("dict — пары «ключ → значение»", "dict — key-to-value mapping"),
        "lab.dataStructures.order.prompt": ("Журнал попыток должен хранить повторы в исходном порядке. Какой контейнер подходит?", "An attempt log must keep repeated entries in their original order. Which container fits?"),
        "lab.dataStructures.order.explanation": ("list сохраняет порядок и каждое повторение, а также даёт доступ по позиции. Последовательный поиск может просмотреть много элементов; зато список прямо соответствует требованиям журнала.", "A list preserves order and every repeated entry and supports positional access. A sequential search may inspect many items, but the list directly fits the log requirements."),
        "lab.dataStructures.membership.prompt": ("Нужно хранить названия уже пройденных тем без дублей; порядок не нужен, важна проверка принадлежности. Какой контейнер выбрать?", "Store completed topic names without duplicates; order does not matter, and membership checks do. Which container fits?"),
        "lab.dataStructures.membership.explanation": ("set хранит только разные хешируемые значения и подходит для принадлежности; индексов и заданного порядка у него нет. Он отбрасывает дубли, но проверку фактического расхода памяти всё равно делай на своих данных.", "A set stores distinct hashable values and supports membership; it has no indexes or defined order. It removes duplicates, but still measure memory with representative data when that matters."),
        "lab.dataStructures.mapping.prompt": ("По уникальному session_id нужно находить и менять длительность занятия. Какой контейнер выражает эту связь напрямую?", "Use a unique session_id to find and update a session duration. Which container expresses this mapping directly?"),
        "lab.dataStructures.mapping.explanation": ("dict связывает уникальные хешируемые ключи со значениями и сохраняет порядок добавления ключей. Обновление существующего ключа меняет связанное значение; это не то же самое, что хранить несколько строк с повторяющимися ID.", "A dict maps unique hashable keys to values and preserves key insertion order. Updating an existing key changes its associated value; this is not the same as keeping repeated rows with duplicate IDs."),
        "lab.dataStructures.correct": ("Подходит", "Fits the requirements"),
        "lab.dataStructures.incorrect": ("Сверь требования и попробуй другой вариант", "Check the requirements and try another choice"),
        "lab.dataStructures.check": ("Проверить выбор", "Check choice"),
        "lab.dataStructures.next": ("Дальше", "Next"),
        "lab.dataStructures.complete": ("Три сценария разобраны", "All three scenarios reviewed"),
        "lab.dataStructures.restart": ("Пройти ещё раз", "Try again"),
        "lab.dataStructures.limit": ("Размеры контейнеров не универсальны: sys.getsizeof показывает только сам объект, а не вложенные элементы. Тренажёр не запускает benchmark и не обещает постоянную сложность операций.", "Container sizes are not universal: sys.getsizeof reports only the object itself, not referenced items. This trainer runs no benchmark and promises no fixed operation complexity."),
        "lab.loopTraceHint": ("Сначала предскажи результат функции. Потом открывай по одному шагу: цикл берёт число, условие проверяет остаток от деления на 2, а счётчик меняется только для чётных.", "Predict the function result first. Then reveal one step at a time: the loop takes a number, the condition checks its remainder when divided by 2, and the counter changes only for even values."),
        "lab.loopTraceInput": ("Входной список для функции подсчёта чётных чисел", "Input list for the even-number counting function"),
        "lab.loopTraceScenario": ("Набор чисел", "Number set"),
        "lab.loopTraceScenario.mixed": ("Обычный пример", "Mixed example"),
        "lab.loopTraceScenario.zero-negative": ("Ноль и отрицательное число", "Zero and a negative number"),
        "lab.loopTraceScenario.empty": ("Пустой список", "Empty list"),
        "lab.loopTraceScenario.larger-values": ("Другой набор", "Another set"),
        "lab.loopTraceCode": ("Псевдоисполнение функции: считает чётные числа в списке", "Trace of a function that counts even numbers in a list"),
        "lab.loopTracePrediction": ("Сколько вернёт функция?", "What will the function return?"),
