        "lab.debugging.hint": ("Сначала найди симптом и выбери следующий проверяемый шаг. Подсказка не чинит программу автоматически.", "Identify the symptom first, then choose a testable next step. The hint does not fix the program automatically."),
        "lab.debugging.scenarioPicker": ("Сценарий ошибки", "Error scenario"),
        "lab.debugging.scenario.name-error": ("Неизвестное имя", "Undefined name"),
        "lab.debugging.scenario.index-error": ("Выход за границу списка", "List boundary"),
        "lab.debugging.scenario.assertion-error": ("Не прошла проверка", "Failed assertion"),
