        "tutor.officialReferencesCaveat": ("Ссылки взяты из урока; содержимое страниц здесь не перепроверяется.", "Links come from the lesson; page content is not rechecked here."),
        "tutor.sourceCheckedAt": ("Официальная страница проверена", "Official page checked"),
        "tutor.sourceSnapshotFetchedAt": ("Текст страницы загружен", "Page text snapshot fetched"),
        "tutor.publisherPublishedAt": ("Дата публикации по данным страницы", "Published (page-declared)"),
        "tutor.publisherUpdatedAt": ("Дата обновления по данным страницы", "Updated (page-declared)"),
        "tutor.publisherDateCaveat": ("Даты указаны страницей; ColiDev не проверяет их независимо.", "Dates are declared by the page; ColiDev does not independently verify them."),
        "tutor.sourceLicense": ("Лицензия", "License"),
        "tutor.sourceLicenseTerms": ("условия", "terms"),
        "tutor.sourceCheckCaveat": ("Это дата из заметки, не гарантия актуальности фактов.", "This date is note metadata, not a guarantee that facts are current."),
        "tutor.sourceReviewInterval": ("Интервал перепроверки, дней", "Review interval, days"),
