        "tutor.sourceReviewScheduleCaveat": ("Это напоминание по графику автора, а не проверка актуальности содержания.", "This is an author-scheduled reminder, not a content freshness check."),
        "tutor.modifiedDateUnavailable": ("Дата изменения источника недоступна", "Source modification date unavailable"),
        "tutor.localUnavailable": ("Локальная модель Ollama не готова. Установи выбранную модель или переключись на «Авто».", "The configured Ollama model is not ready. Install it or switch to Auto."),
        "tutor.localEndpointBlocked": ("Адрес Ollama не подтверждён как этот Mac. Для локального режима укажи localhost или loopback IP.", "Ollama is not confirmed to be on this Mac. Use localhost or a loopback IP for Local mode."),
        "tutor.backendNotReady": ("Локальный учебный сервис ещё не готов. Подожди запуска или проверь его состояние в настройках.", "The local learning service is not ready yet. Wait for startup or check its status in Settings."),
        "tutor.routeStatusUnknown": ("Сервис запущен, но статус моделей не получен. Открой Центр управления и проверь доступность маршрута ИИ.", "The service is running, but model status has not arrived. Open Control Center and check AI route availability."),
        "tutor.autoRouteUnavailable": ("В режиме «Авто» сейчас нет доступного маршрута. Настрой модель или провайдера в Центре управления; облачные вызовы не включаются сами.", "No route is currently available in Auto mode. Configure a model or provider in Control Center; cloud calls are never enabled automatically."),
        "settings.local": ("Локальные данные", "Local data"),
        "settings.localBody": ("Прогресс и заметки рефлексии хранятся локально на этом Mac. Текст заметок не отправляется ИИ. Авто-режим может отправлять моделям вопросы, контекст урока и найденные учебные фрагменты. Google Search включается отдельно после явного разрешения облачных вызовов и может расходовать квоту. Отдельная фоновая проверка источников при наличии интернета может получать одобренные публичные страницы, но не отправляет ваши вопросы или заметки.", "Progress and reflection notes are stored on this Mac. Reflection notes are not sent to AI. Auto mode may send questions, lesson context, and retrieved learning excerpts to models. Google Search requires explicit permission for cloud calls and may use quota. Separate background source checks may fetch approved public pages when internet is available, but they do not send your questions or notes."),
        "settings.version": ("Статус", "Status"),
        "settings.preview": ("Ранний прототип", "Early prototype"),
        "updates.title": ("Обновления", "Updates"),
        "updates.installed": ("Установленная версия", "Installed version"),
        "updates.auto": ("Автоматически проверять обновления; установку подтверждать", "Automatically check for updates; confirm installation"),
        "updates.check": ("Проверить и установить обновление…", "Check for and install update…"),
        "updates.autoUnavailable": ("Автообновление пока не настроено для этой beta", "Automatic updates are not configured for this beta"),
        "updates.autoSetup": ("Для безопасной установки нужны подписанная сборка, нотарификация macOS и ключ проверки обновлений. Пока можно скачать опубликованную версию вручную.", "Safe installation requires a signed build, macOS notarization, and an update verification key. You can download a published version manually for now."),
        "updates.history": ("Опубликованные версии", "Published versions"),
        "updates.refresh": ("Обновить список", "Refresh list"),
        "updates.unavailable": ("Не удалось загрузить версии", "Could not load releases"),
        "updates.retry": ("Повторить", "Try again"),
        "updates.loading": ("Загружаю версии…", "Loading releases…"),
        "updates.empty": ("Опубликованных версий пока нет.", "There are no published releases yet."),
        "updates.manualHelp": ("Скачивание откроется в браузере. Распакуй архив, перетащи ColiDev.app в «Программы» и подтверди замену. Учебный прогресс хранится отдельно от приложения.", "The download opens in your browser. Extract the archive, move ColiDev.app to Applications, and confirm replacement. Learning progress is stored separately from the app."),
        "updates.download": ("Скачать сборку для этого Mac", "Download build for this Mac"),
        "updates.noBuild": ("Для этой версии нет архива для архитектуры этого Mac.", "This release has no archive for this Mac architecture."),
        "updates.github": ("Открыть страницу версии на GitHub", "Open release page on GitHub"),
        "updates.beta": ("Тестовая версия", "Pre-release"),
        "updates.expanded": ("Развёрнуто", "Expanded"),
        "updates.collapsed": ("Свёрнуто", "Collapsed"),
        "updates.unknownVersion": ("Версия не указана", "Version unavailable"),
        "updates.issue.crashesAtLaunch.badge": ("Не запускается", "Does not launch"),
        "updates.issue.crashesAtLaunch.message": ("Эта версия падает при запуске — используйте Beta 12 или новее. Ссылка на скачивание скрыта.", "This build crashes at launch — use Beta 12 or later. The download link is hidden."),
        "management.title": ("Центр управления ColiDev", "ColiDev Control Center"),
        "management.subtitle": ("Курсы, официальные источники и состояние локального ИИ в одном месте.", "Courses, official sources, and local AI status in one place."),
        "management.overview": ("Обзор", "Overview"),
